// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 fundAmount) public {
        fundAmount = bound(fundAmount, 1, 1_000_000 ether);

        vm.deal(address(this), fundAmount);

        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        assert(address(c).balance == fundAmount);

        address recipient = address(0xBEEF);
        vm.prank(address(this));
        c.withdrawAll(recipient);

        assertTrue(address(c).balance == 0);
    }
}
